13	// HookTrustGaps returns the snake_case event labels declared in the hooks.json
14	// Codex discovers that don't have a matching approval entry in the
15	// user's Codex config.toml. Matching parses the full
16	// `<hooks.json>:<event>:<group>:<handler>` key, accepts any valid indexes, and
17	// compares canonicalized hook paths.
18	//
19	// This is the structural form of the trust check: we don't recompute
20	// Codex's hook hash, we only look at key presence. That misses the
21	// "command changed but key is still there" case (status = Modified),
22	// but Codex's own startup warning catches those — our purpose here is
23	// to surface fresh additions like "you trusted three hooks last month
24	// but a new PostToolUse arrived" inside our SessionStart welcome.
25	//
26	// Returns nil when:
27	//   - .codex/hooks.json doesn't exist (entire isn't installed in this repo)
28	//   - The authoritative hook location can't be resolved
29	//   - The checkout has no local .codex project layer
30	//   - The user's config.toml can't be read
31	//   - Every declared event already has a state entry
32	func HookTrustGaps(ctx context.Context) []string {
33		return InspectHookTrust(ctx).Gaps
34	}
