44	// InspectHookTrust reports declared events and whether the user's Codex config
45	// contains approval records for them. Known is false when config.toml cannot be
46	// read, so callers do not mistake an unavailable trust check for active hooks.
47	func InspectHookTrust(ctx context.Context) HookTrustInspection {
48		discovery := ResolveHookDiscovery(ctx)
49		if discovery.State != HookDiscoveryResolved || !discovery.ProjectLayerExists() {
50			return HookTrustInspection{}
51		}
52		inspection := inspectDiscoveredHookConfig(ctx, discovery.DiscoveredHooks)
53		if inspection.State != HookFileEntire {
54			return HookTrustInspection{}
55		}
56		return inspectHookTrustForDeclared(discovery.DiscoveredHooks.Path(), inspection.Declared)
57	}
