59	func inspectHookTrust(hooksJSONPath string) HookTrustInspection {
60		declared, ok := declaredCodexEvents(hooksJSONPath)
61		if !ok || len(declared) == 0 {
62			return HookTrustInspection{}
63		}
64		return inspectHookTrustForDeclared(hooksJSONPath, declared)
65	}
