67	func inspectHookTrustForDeclared(hooksJSONPath string, declared []string) HookTrustInspection {
68		if len(declared) == 0 {
69			return HookTrustInspection{}
70		}
71		inspection := HookTrustInspection{Declared: declared}
72	
73		configPath := codexConfigPath()
74		if configPath == "" {
75			return inspection
76		}
77		trusted, ok := readCodexTrustedKeys(configPath)
78		if !ok {
79			return inspection
80		}
81		inspection.Known = true
82	
83		for _, ev := range declared {
84			if !codexHasTrustedEvent(trusted, hooksJSONPath, ev) {
85				inspection.Gaps = append(inspection.Gaps, ev)
86			}
87		}
88		return inspection
