102	// of every event that has at least one handler declared. The bool reports
103	// whether the read+parse succeeded — false on missing/malformed file so
104	// callers can stay silent rather than mid-flow noise.
105	func declaredCodexEvents(hooksJSONPath string) ([]string, bool) {
106		document, err := readHooksDocument(hooksJSONPath)
