114	func declaredCodexEventsFromDocument(document *hooksDocument) ([]string, error) {
115		var events []string
116		add := func(event, label string) error {
117			var groups []MatcherGroup
118			if err := parseHookType(document.rawHooks, event, &groups); err != nil {
119				return err
120			}
121			for _, g := range groups {
122				if len(g.Hooks) > 0 {
123					events = append(events, label)
124					break
125				}
126			}
127			return nil
128		}
129		for _, event := range HookEventSpecs() {
130			if err := add(event.Event, event.Label); err != nil {
131				return nil, err
132			}
133		}
134		return events, nil
135	}
