158	// codexTrustStateHeaderRegex matches `[hooks.state."<key>"]` headers in
159	// the user's Codex config.toml. Quote-only — Codex's own writer emits
160	// quoted keys (codex-rs/tui/src/app/background_requests.rs:874), and
161	// looser parsing would invite false matches in user-edited configs.
162	var codexTrustStateHeaderRegex = regexp.MustCompile(`(?m)^\[hooks\.state\."([^"]+)"\]`)
163	
164	func readCodexTrustedKeys(configPath string) (map[string]struct{}, bool) {
165		file, err := os.Open(configPath) //nolint:gosec // path resolved from CODEX_HOME or HOME
166		if err != nil {
167			return nil, false
168		}
169		defer file.Close()
170		data, err := io.ReadAll(io.LimitReader(file, maxHooksFileBytes+1))
171		if err != nil || len(data) > maxHooksFileBytes {
172			return nil, false
173		}
174		keys := make(map[string]struct{})
175		for _, m := range codexTrustStateHeaderRegex.FindAllStringSubmatch(string(data), -1) {
176			keys[m[1]] = struct{}{}
177		}
178		return keys, true
179	}
