181	func codexHasTrustedEvent(keys map[string]struct{}, hooksPath, event string) bool {
182		canonicalHooksPath, err := canonicalPath(hooksPath)
183		if err != nil {
184			return false
185		}
186		for key := range keys {
187			trustedHooksPath, trustedEvent, ok := parseCodexTrustKey(key)
188			if !ok || trustedEvent != event {
189				continue
190			}
191			// Codex preserves nested symlinks in trust keys, while Git resolves
192			// worktree roots to their physical paths.
193			canonicalTrustedPath, err := canonicalPath(trustedHooksPath)
194			if err == nil && canonicalTrustedPath == canonicalHooksPath {
195				return true
196			}
197		}
198		return false
199	}
200	
201	func parseCodexTrustKey(key string) (hooksPath, event string, ok bool) {
202		handlerSeparator := strings.LastIndexByte(key, ':')
203		if handlerSeparator < 0 {
204			return "", "", false
205		}
206		groupSeparator := strings.LastIndexByte(key[:handlerSeparator], ':')
207		if groupSeparator < 0 {
208			return "", "", false
209		}
210		eventSeparator := strings.LastIndexByte(key[:groupSeparator], ':')
211		if eventSeparator < 0 {
212			return "", "", false
213		}
214		if _, err := strconv.Atoi(key[groupSeparator+1 : handlerSeparator]); err != nil {
215			return "", "", false
216		}
217		if _, err := strconv.Atoi(key[handlerSeparator+1:]); err != nil {
218			return "", "", false
219		}
220		return key[:eventSeparator], key[eventSeparator+1 : groupSeparator], true
221	}
